<!doctype html><html><head><meta charset="utf-8"><title>Laporan Order</title><style>body{font:12px Arial;color:#111}h1{font-size:20px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #bbb;padding:6px;text-align:left}th{background:#eee}.meta{color:#555;margin-bottom:12px}@media print{button{display:none}}</style></head><body><button onclick="window.print()">Print / Simpan PDF</button><h1>Laporan Order</h1><div class="meta">Filter: {{ collect($filters ?? [])->filter()->map(fn ($value, $key) => str_replace('_', ' ', $key).': '.$value)->implode(' | ') ?: 'Semua data' }}</div><table><thead><tr><th>Booking</th><th>Tanggal</th><th>Status</th><th>Customer</th><th>Marketing</th><th>Rute</th><th>Harga Jual</th><th>Modal</th><th>Laba</th></tr></thead><tbody>@foreach($orders as $order)<tr><td>{{ $order->booking_number }}</td><td>{{ $order->order_date->format('d/m/Y') }}</td><td>{{ ucfirst($order->status) }}</td><td>{{ $order->customer }}</td><td>{{ $order->marketing }}</td><td>{{ $order->origin }} → {{ $order->destination }}</td><td>{{ number_format($order->selling_price, 2, ',', '.') }}</td><td>{{ number_format($order->total_capital, 2, ',', '.') }}</td><td>{{ number_format($order->profit, 2, ',', '.') }}</td></tr>@endforeach</tbody></table></body></html>
